export function buildHistorySchedule(startISO = null) {
  return buildScheduleFor(HISTORY_MODULES, startISO, HISTORY_META.cadenceDays);
}

export function historyProgressSummary(progress = {}) {
  return progressSummaryFor(HISTORY_MODULES, progress);
}

export function exportHistoryCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: HISTORY_META,
    modules: buildHistorySchedule(startISO),
    sessionFlow: HISTORY_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function historyRefs() {
  const seen = new Set();
  for (const m of HISTORY_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((HISTORY_META.wordFirst && HISTORY_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

// =============================================================================
// VOICES OF THE TIME + THE RECORD, DATED (DR-0580)
// =============================================================================
// Darrell, 2026-09-23: "History should have quoted Historical figures most
// important and familiar words in context of the time..." and "Timelines
// management". Every lesson now carries `voices` — the figures' own words,
// VERBATIM from a named primary record, with the year, the occasion and why
// the lesson quotes them — and `timeline`, the dated record the lesson rests
// on. Neither is decoration, and neither is trusted on the author's word:
//   * historyVoiceFaults(m)    — shape, source host, no elision, no Scripture
//                                ref smuggled in after a quotation.
//   * historyTimelineFaults(m) — ascending years; EVERY year the lesson names
//                                is on its timeline and every timeline year is
//                                named by the lesson or a voice (the gate that
//                                makes the timeline managed rather than typed).
//   * scripts/history-voices-witness.mjs — fetches every source on a GitHub
//                                runner (this sandbox has no road to those
//                                hosts) and proves the words are in it.
// The KJV walk in history-course.test.js ignores these quotations on purpose:
// it only checks a span followed by (Book c:v), and a historical figure's words
// never carry one.

/** The primary-record hosts a voice may cite. A new host is a deliberate add. */
export const HISTORY_SOURCE_HOSTS = [
  'avalon.law.yale.edu', 'teachingamericanhistory.org', 'www.presidency.ucsb.edu',
  'www.law.cornell.edu', 'www.gutenberg.org', 'www.archives.gov', 'www.nps.gov',
  'www.thesojournertruthproject.com', 'www.africa.upenn.edu',
  'www.freedmen.umd.edu', 'en.wikisource.org',
];

const YEAR_RE = /\b(1[5-9]\d\d|20[0-2]\d)\b/g;
// RECORD HOSTS FOR DATED ENTRIES (2026-09-24, DR-0597). Darrell: "Where did the
// rigor for this lesson come from?! Not our process!" A timeline entry may name
// a record in prose and still rest on memory. From this record on, a dated
// entry that carries a `source` ({ title, url, phrase }) is PROBED by the
// witness like a voice: the page must answer and hold the phrase. The hosts
// below are the ones that answered a GitHub runner with 200 on 2026-09-24
// (history-voices-witness probe run); a page that refused the runner is not
// on this list and cannot be cited.
export const HISTORY_RECORD_HOSTS = [
  // filled from the probe run's answering hosts in the commit that cites them
];
const HISTORY_NOT_PROSE = new Set(['stories', 'voices', 'timeline']);
const walkText = (node, fn) => {
  if (typeof node === 'string') fn(node);
  else if (Array.isArray(node)) node.forEach((v) => walkText(v, fn));
  else if (node && typeof node === 'object') Object.values(node).forEach((v) => walkText(v, fn));
};
const wordCount = (t) => (String(t || '').match(/[A-Za-z0-9’']+/g) || []).length;

/** Every four-digit year the lesson's own prose names (parables excluded). */
export function historyYearsNamed(m) {
  const out = new Set();
  for (const [k, v] of Object.entries(m || {})) {
    if (HISTORY_NOT_PROSE.has(k)) continue;
    walkText(v, (t) => { for (const y of t.match(YEAR_RE) || []) out.add(Number(y)); });
  }
  return [...out].sort((a, b) => a - b);
}

/** The years a lesson's voices carry — their `year` and any year in their text. */
export function historyVoiceYears(m) {
  const out = new Set();
  for (const v of (m && m.voices) || []) {
    if (Number.isInteger(v.year)) out.add(v.year);
    walkText(v, (t) => { for (const y of t.match(YEAR_RE) || []) out.add(Number(y)); });
  }
  return [...out].sort((a, b) => a - b);
}

export function historyVoiceFaults(m) {
  const faults = [];
  const id = (m && m.id) || '?';
  const voices = (m && m.voices) || [];
  if (!Array.isArray(voices) || voices.length < 2) faults.push(`${id}: fewer than two voices`);
  voices.forEach((v, i) => {
    const at = `${id}.voices[${i}]`;
    if (!v || typeof v !== 'object') { faults.push(`${at}: not an object`); return; }
    if (wordCount(v.speaker) < 1) faults.push(`${at}: no speaker`);
    if (!Number.isInteger(v.year) || v.year < 1500 || v.year > 2030) faults.push(`${at}: year is not a four-digit year`);
    if (wordCount(v.where) < 6) faults.push(`${at}: "where" does not set the occasion`);
    if (!v.source || wordCount(v.source.title) < 2) faults.push(`${at}: no source title`);
    let host = '';
    try { host = new URL(String((v.source && v.source.url) || '')).host; } catch { /* not a URL — reported below */ }
    if (!/^https:\/\//.test(String((v.source && v.source.url) || ''))) faults.push(`${at}: source url is not https`);
    else if (!HISTORY_SOURCE_HOSTS.includes(host)) faults.push(`${at}: source host ${host} is not a listed primary-record host`);
    if (wordCount(v.words) < 8) faults.push(`${at}: fewer than eight words quoted`);
    if (/\.\.\.|…/.test(String(v.words || ''))) faults.push(`${at}: elision inside a quotation`);
    if (/\([1-3]?\s?[A-Za-z]+\s+\d+:[\d\-,\s]+\)/.test(String(v.words || ''))) faults.push(`${at}: a Scripture reference inside a historical quotation`);
    if (wordCount(v.why) < 6) faults.push(`${at}: no reason the lesson quotes it`);
    if (v.note != null && typeof v.note !== 'string') faults.push(`${at}: note is not text`);
  });
  return faults;
}

export function historyTimelineFaults(m) {
  const faults = [];
  const id = (m && m.id) || '?';
  const tl = (m && m.timeline) || [];
  if (!Array.isArray(tl) || tl.length < 3) faults.push(`${id}: fewer than three dated entries`);
  let last = 0;
  tl.forEach((t, i) => {
    const at = `${id}.timeline[${i}]`;
    if (!t || typeof t !== 'object') { faults.push(`${at}: not an object`); return; }
    if (!Number.isInteger(t.year) || t.year < 1500 || t.year > 2030) faults.push(`${at}: year is not a four-digit year`);
    else { if (t.year < last) faults.push(`${at}: ${t.year} is out of order after ${last}`); last = t.year; }
    if (wordCount(t.event) < 5) faults.push(`${at}: event is not a sentence`);
    if (wordCount(t.record) < 3) faults.push(`${at}: no record named`);
    if (t.source != null) {
      const src = t.source && typeof t.source === 'object' ? t.source : {};
      if (wordCount(src.title) < 2) faults.push(`${at}: source has no title`);
      let host = '';
      try { host = new URL(String(src.url || '')).host; } catch { /* reported below */ }
      if (!/^https:\/\//.test(String(src.url || ''))) faults.push(`${at}: source url is not https`);
      else if (!HISTORY_SOURCE_HOSTS.includes(host) && !HISTORY_RECORD_HOSTS.includes(host)) faults.push(`${at}: source host ${host} is not a listed record host`);
      if (wordCount(src.phrase) < 3) faults.push(`${at}: source phrase is under three words (the witness needs words to find on the page)`);
      if (/\.\.\.|…/.test(String(src.phrase || ''))) faults.push(`${at}: elision inside the source phrase`);
    }
  });
  const on = new Set(tl.map((t) => t && t.year));
  const named = historyYearsNamed(m);
  const voiced = historyVoiceYears(m);
  for (const y of named) if (!on.has(y)) faults.push(`${id}: the lesson names ${y} and the timeline does not carry it`);
  for (const y of voiced) if (!on.has(y)) faults.push(`${id}: a voice carries ${y} and the timeline does not`);
  const known = new Set([...named, ...voiced]);
  for (const y of on) if (!known.has(y)) faults.push(`${id}: the timeline carries ${y} and neither the lesson nor a voice names it`);
  return faults;
}

/** The whole course on one line of years — every lesson's dated record, merged and sorted. */
export function historyTimeline(modules = HISTORY_MODULES) {
  const out = [];
  modules.forEach((m, order) => {
    for (const t of (m && m.timeline) || []) out.push({ ...t, lessonId: m.id, lessonTitle: m.title, order });
  });
  return out.sort((a, b) => (a.year - b.year) || (a.order - b.order));
}

